import pytest

from minisheet.refs import Ref, parse_range, parse_ref, to_a1


# B§1 table rows
def test_parse_ref_b12():
    assert parse_ref("B12") == Ref(1, 11, False, False)


def test_parse_ref_absolute_zz9999():
    assert parse_ref("$zz$9999") == Ref(701, 9998, True, True)


def test_parse_range_mixed_flags():
    assert parse_range("$C3:A$1") == (Ref(0, 0, False, True), Ref(2, 2, True, False))


def test_to_a1_abs_col():
    assert to_a1(Ref(26, 0, True, False)) == "$AA1"


def test_parse_ref_a0_rejected():
    with pytest.raises(ValueError):
        parse_ref("A0")


def test_parse_ref_aaa1_rejected():
    with pytest.raises(ValueError):
        parse_ref("AAA1")


# B§1 prose
def test_parse_ref_a1_is_origin():
    assert parse_ref("A1") == Ref(0, 0)


def test_parse_ref_a10000_rejected():
    with pytest.raises(ValueError):
        parse_ref("A10000")


def test_parse_ref_leading_zero_row_rejected():
    with pytest.raises(ValueError):
        parse_ref("A01")


def test_parse_ref_lowercase_accepted():
    assert parse_ref("b2") == Ref(1, 1)


def test_parse_ref_whitespace_rejected():
    with pytest.raises(ValueError):
        parse_ref(" A1")


def test_parse_ref_empty_rejected():
    with pytest.raises(ValueError):
        parse_ref("")


def test_parse_range_a1_a1_valid():
    assert parse_range("A1:A1") == (Ref(0, 0), Ref(0, 0))


def test_parse_range_normalizes_order():
    assert parse_range("C3:A1") == (Ref(0, 0), Ref(2, 2))


def test_parse_range_tie_uses_first_corner_flags():
    # same column on both corners: first corner's abs_col wins
    assert parse_range("$A1:A$5") == (Ref(0, 0, True, False), Ref(0, 4, False, True))


def test_parse_range_bad_corner_rejected():
    with pytest.raises(ValueError):
        parse_range("A1:A0")


# Review Focus
def test_a01_rejected():
    with pytest.raises(ValueError):
        parse_ref("A01")


def test_range_bare_cell():
    with pytest.raises(ValueError):
        parse_range("A1")


def test_to_a1_out_of_range():
    with pytest.raises(ValueError):
        to_a1(Ref(702, 0))


def test_to_a1_row_out_of_range():
    with pytest.raises(ValueError):
        to_a1(Ref(0, 9999))


def test_to_a1_roundtrip_b12():
    assert to_a1(Ref(1, 11, False, False)) == "B12"

